def parse_date(excel_date):
    """Convert Excel serial date to YYYY-MM-DD string."""
    if excel_date == "":
        return None
    try:
        # Excel's epoch is 1899-12-30 (or 1900-01-00)
        # Some systems use 1900-01-01, but we'll use 1899-12-30
        # Excel incorrectly treats 1900 as a leap year, so we adjust
        epoch = datetime(1899, 12, 30)
        days = float(excel_date)
        date = epoch + timedelta(days=days)
        return date.strftime("%Y-%m-%d")
    except (ValueError, TypeError):
